                onEarnPoints={handleEarnPoints}
                currentPoints={points}
                numberColor={NUMBER_COLORS.find(c => c.id === selectedNumberColorId)?.uiClass}
                purchasedSkills={purchasedSkills}
            />
        )}

        {/* Purchase Modal */}
        {purchaseModal && (
            <div className="fixed inset-0 bg-stone-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in">
                <div className="bg-white dark:bg-stone-800 rounded-2xl p-6 w-full max-w-sm shadow-xl animate-pop text-center">
                    <h3 className="text-lg font-bold mb-2">Purchase Item?</h3>
                    <p className="text-stone-600 dark:text-stone-300 mb-6">
                        Unlock <span className="font-bold text-t-primary">{purchaseModal.item.name}</span> for <span className="font-bold text-blue-500">{purchaseModal.item.cost}</span> gems?
                    </p>
                    <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setPurchaseModal(null); }} className="flex-1 py-3 bg-stone-100 dark:bg-stone-700 text-stone-600 dark:text-stone-300 font-bold rounded-xl">Cancel</button>
                         <button onClick={confirmPurchase} disabled={points < purchaseModal.item.cost} className={`flex-1 py-3 text-white font-bold rounded-xl ${points >= purchaseModal.item.cost ? 'bg-blue-500 shadow-md shadow-blue-500/20' : 'bg-stone-400 cursor-not-allowed'}`}>
                             {points >= purchaseModal.item.cost ? 'Purchase' : 'Need Gems'}
                         </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

                  {/* NUMBER COLORS */}
                  <div>
                      <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                      <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                          const isPurchased = purchasedNumberColors.includes(num.id);
                          const isSelected = selectedNumberColorId === num.id;
                          return (
                              <div key={num.id} className="flex flex-col items-center gap-1">
                                  <button onClick={() => isPurchased ? handleSelectNumberColor(num.id) : initiatePurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                      <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                          <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                      </div>
                                      {!isPurchased && (
                                          <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                              <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                          </div>
                                      )}
                                  </button>
                                  <span className="text-[10px] text-t-secondary font-medium truncate w-full text-center">{num.name}</span>
                              </div>
                          );
                      })}</div>
                  </div>
              </div>
              <div className="h-safe-bottom w-full shrink-0" />
         </div>
    </div>
)}

import React, { useState, useEffect } from 'react';
