                                            </div>

                                            <div className="space-y-1">
                                                {offer.includes && offer.includes.map(inc => (
                                                    <div key={inc} className="flex items-center gap-2 text-stone-800">
                                                        <Icons.Check className="w-4 h-4 text-green-500" />
                                                        <span className="text-sm font-bold">{inc}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                ))}

                                <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">PACKS</h3>
                                <div className="grid grid-cols-2 gap-3 mb-8">
                                    {DIAMOND_OFFERS.filter(o => o.type === 'pack').map(offer => (
                                        <div key={offer.id} className="bg-gradient-to-b from-blue-50 to-white dark:from-stone-800 dark:to-stone-900 rounded-3xl p-4 flex flex-col items-center justify-between shadow-sm border border-blue-100 dark:border-stone-700 h-48">
                                            <div className="flex-1 flex flex-col items-center justify-center gap-1">
                                                <Icons.Diamond className="w-10 h-10 text-blue-500 fill-current drop-shadow-sm" />
                                                <span className="text-2xl font-bold text-stone-900 dark:text-t-primary">{offer.diamonds}</span>
                                                <span className="text-sm font-medium text-stone-400">{offer.title}</span>
                                            </div>
                                            <button onClick={() => handleBuyOffer(offer)} className="w-full py-3 btn-premium-silver rounded-xl text-sm font-bold active:scale-95 transition">
                                                {offer.priceLabel}
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">BUNDLES</h3>
                                <div className="space-y-4 mb-8">
                                    {DIAMOND_OFFERS.filter(o => o.type === 'bundle').map(offer => (
                                        <button 
                                            key={offer.id}
                                            onClick={() => handleBuyOffer(offer)}
                                            className={`w-full relative overflow-hidden rounded-2xl transition-all active:scale-95 text-left group
                                                ${offer.gradientClass ? offer.gradientClass : 'bg-t-surface border border-t-border'}
                                                shadow-sm
                                            `}
                                        >
                                            <div className="p-5 flex flex-row items-center justify-between gap-4 relative z-10">
                                                <div className="flex flex-col items-start gap-1">
                                                    <h3 className="text-lg font-bold leading-none text-stone-900">
                                                        {offer.title}
                                                    </h3>
                                                    {offer.includes && (
                                                        <div className="flex flex-col gap-0.5 mt-1">
                                                            {offer.includes.map(inc => (
                                                                <span key={inc} className="text-xs flex items-center gap-1 text-stone-700">
                                                                    <Icons.Check className="w-3 h-3" /> {inc}
                                                                </span>
                                                            ))}
                                                        </div>
                                                    )}
                                                </div>

                                                <div className="flex flex-col items-end gap-1">
                                                     <div className="flex items-center gap-1">
                                                         <span className="text-2xl font-black text-stone-900">{offer.diamonds}</span>
                                                         <Icons.Diamond className="w-6 h-6 text-blue-500 fill-current" />
                                                     </div>
                                                     <div className="px-3 py-1.5 rounded-lg text-sm font-bold btn-premium-silver">
                                                         {offer.priceLabel}
                                                     </div>
                                                </div>
                                            </div>
                                        </button>
                                    ))}
                                </div>

                                <div className="p-4 bg-t-surface-sec rounded-xl text-center mt-6">
