        const plus = <span className="text-stone-900/40 font-black text-xl mx-0.5">+</span>;

        switch(id) {
            case 'bundle_skill':
                return (
                    <div className="flex items-center gap-2 mt-2 mb-2 pl-1">
                        <div className={iconBase}><Icons.Auto className="w-4 h-4 text-amber-600 fill-current" /></div>
                        {plus}
                        <div className={iconBase}><Icons.Scan className="w-4 h-4 text-red-600" /></div>
                    </div>
                );
            case 'bundle_cosmetic':
                return (
                    <div className="flex items-center gap-2 mt-2 mb-2 pl-1">
                        {/* Static BG Representation */}
                        <div className={`${iconBase} overflow-hidden bg-gradient-to-br from-orange-100 to-rose-100`}>
                            <div className="w-full h-full opacity-80" />
                        </div>
                        {plus}
                        {/* Dynamic BG Representation */}
                        <div className={`${iconBase} overflow-hidden bg-gradient-to-br from-emerald-200 via-teal-100 to-fuchsia-200`}>
                             <div className="w-full h-full opacity-80" />
                        </div>
                    </div>
                );
            case 'bundle_pro':
                return (
                    <div className="flex items-center gap-1.5 mt-2 mb-2 pl-1">
                        <div className={iconBase}><Icons.Auto className="w-4 h-4 text-amber-600 fill-current" /></div>
                        <div className={iconBase}><Icons.Scan className="w-4 h-4 text-red-600" /></div>
                        <div className={iconBase}><Icons.Reveal className="w-4 h-4 text-purple-600" /></div>
                        {plus}
                         <div className={`${iconBase} bg-white/80`}><span className="text-sm font-bold text-shine-diamond">5</span></div>
                    </div>
                );
            default:
                return null;
