                                className={`w-full h-48 relative overflow-hidden rounded-[1.75rem] p-5 shadow-xl transition-transform mb-6 text-left ${offer.gradientClass || 'bg-white'} ${isPurchased ? 'shadow-none opacity-50 grayscale cursor-not-allowed' : 'shadow-amber-900/5 active:scale-[0.99] group'}`}
                             >
                                {/* Big Faded Icon Logo on Side */}
                                <div className="absolute -right-6 -bottom-10 opacity-[0.05] pointer-events-none transform rotate-12">
                                     <Icons.Diamond className="w-48 h-48 text-stone-900 fill-current" />
                                </div>

                                <div className="relative z-10 flex flex-col justify-between h-full">
                                    {/* Top Row: Info & Button */}
                                    <div className="flex justify-between items-start w-full">
                                        <div className="flex flex-col items-start gap-0.5">
                                             {/* Badge */}
                                             {!isPurchased && (
                                                <div className="inline-block px-2 py-0.5 rounded-md bg-orange-100 text-orange-700 text-[10px] font-black tracking-widest uppercase mb-1 border border-orange-200/50">
                                                    {offer.badge || "BEST VALUE"}
                                                </div>
                                             )}
                                             {/* Title Group */}
                                             <h2 className="text-xl font-bold text-stone-900 leading-none">{offer.title}</h2>
                                             <p className="text-sm font-semibold text-stone-500 mt-1">{offer.subtitle}</p>
                                        </div>

                                        {/* Price Badge (Visual Only) */}
                                        <div 
                                            className={`text-[11px] font-bold px-4 py-2 rounded-xl shadow-lg transition-all whitespace-nowrap ${isPurchased ? 'bg-stone-400 text-white shadow-none' : 'bg-stone-800 text-white group-hover:bg-stone-700'}`}
                                         >
                                            {isPurchased ? 'OWNED' : offer.priceLabel}
                                         </div>
                                    </div>

                                    {/* Bottom Row: Features (Left) & Diamonds (Right) */}
                                    <div className="flex justify-between items-end w-full">
                                         {/* Features List - Moved to Left */}
                                         <div className="flex flex-col gap-1 items-start pb-1">
                                             {offer.includes && offer.includes.map(inc => (
                                                 <div key={inc} className="flex items-center gap-1.5">
                                                     <Icons.Check className="w-4 h-4 text-green-600 stroke-[3]" />
                                                     <span className="text-sm font-bold text-stone-700">{inc}</span>
                                                 </div>
                                             ))}
                                         </div>

                                         {/* Diamonds Display - Moved to Right */}
                                         <div className="flex items-center gap-1.5">
                                             <span className="text-4xl font-black text-stone-900 tracking-tighter leading-none">+{offer.diamonds}</span>
                                             {/* Iconic Blue Diamond */}
                                             <Icons.Diamond className="w-7 h-7 text-blue-500 fill-current drop-shadow-sm mb-1" />
                                         </div>
                                    </div>
                                </div>
                            </button>
                        );
                    })}

                    <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">PACKS</h3>
                    <div className="grid grid-cols-4 gap-2 mb-8">
                        {DIAMOND_OFFERS.filter(o => o.type === 'pack').map(offer => (
                            <button 
                                key={offer.id} 
                                onClick={() => onBuyOffer(offer)}
                                className="bg-gradient-to-b from-blue-50 to-white dark:from-stone-800 dark:to-stone-900 rounded-2xl p-1.5 flex flex-col items-center justify-between shadow-sm border border-blue-100 dark:border-stone-700 h-40 active:scale-95 transition-transform"
                            >
                                <div className="flex-1 flex flex-col items-center justify-center gap-0.5 w-full overflow-hidden">
                                    <Icons.Diamond className="w-9 h-9 text-blue-500 fill-current drop-shadow-sm mb-1" />
                                    <span className="text-xl font-black text-stone-900 dark:text-t-primary leading-none">+{offer.diamonds}</span>
                                    <span className="text-xs font-bold text-stone-400 truncate w-full text-center">{offer.title}</span>
                                </div>
                                <div className="w-full py-2 btn-premium-silver rounded-lg text-[11px] font-bold truncate px-1">
                                    {offer.priceLabel}
                                </div>
                            </button>
                        ))}
                    </div>

                    <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">BUNDLES</h3>
                    <div className="space-y-4 mb-8">
                        {DIAMOND_OFFERS.filter(o => o.type === 'bundle').map(offer => {
                            const isPurchased = purchasedBundles.includes(offer.id);

                            return (
                                <button 
                                    key={offer.id}
                                    onClick={() => !isPurchased && onBuyOffer(offer)}
                                    disabled={isPurchased}
                                    className={`w-full relative overflow-hidden rounded-[1.25rem] transition-all text-left group
                                        ${offer.gradientClass ? offer.gradientClass : 'bg-t-surface border border-t-border'}
