                                    `}
                                >
                                    {/* Shimmer for Pro Bundle */}
                                    {offer.id === 'bundle_pro' && !isPurchased && (
                                         <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent z-0 animate-shimmer pointer-events-none" />
                                    )}

                                    <div className="p-4 relative z-10 w-full">
                                        {/* Row 1: Header */}
                                        <div className="flex justify-between items-start w-full mb-0.5">
                                            <h3 className="text-lg font-bold leading-none text-stone-900">{offer.title}</h3>
                                            <div className="flex items-center gap-1">
                                                 <span className="text-2xl font-black text-stone-900 leading-none">+{offer.diamonds}</span>
                                                 <Icons.Diamond className="w-5 h-5 text-blue-500 fill-current drop-shadow-sm" />
                                            </div>
                                        </div>

                                        {/* Row 2: Visuals */}
                                        {renderBundleVisuals(offer.id)}

                                        {/* Row 3: Description & Price */}
                                        <div className="flex justify-between items-end mt-2 w-full">
                                             <div className="flex flex-col gap-0.5 max-w-[70%]">
                                                 {offer.includes?.map(inc => (
                                                     <div key={inc} className="flex items-start gap-1.5 text-stone-800/80">
                                                          <Icons.Check className="w-4 h-4 text-green-600 stroke-[3] mt-0.5 shrink-0" /> 
                                                          <span className="text-sm font-bold leading-tight">{inc}</span>
                                                     </div>
                                                 ))}
                                             </div>

                                             <div className={`px-3 py-1.5 rounded-lg text-xs font-bold shadow-sm min-w-[80px] text-center ${isPurchased ? 'bg-stone-400 text-white' : 'btn-premium-silver'}`}>
                                                 {isPurchased ? 'OWNED' : offer.priceLabel}
                                             </div>
                                        </div>
                                    </div>
                                </button>
                            );
                        })}
                    </div>

                    <div className="p-4 bg-t-surface-sec rounded-xl text-center mt-6">
                        <p className="text-xs text-t-secondary leading-relaxed">
                            Payments are simulated for this demo. No real money is charged.
                        </p>
                        <button 
                            className="mt-2 text-xs font-bold text-t-primary underline" 
                            onClick={() => {
                                if(confirm("Restore Purchases?")) {
                                    alert("Purchases Restored (Simulation)");
                                }
                            }}
                        >
                            Restore Purchases
                        </button>
                    </div>
                </div>
                <div className="h-safe-bottom w-full shrink-0" />
            </div>
        </div>
    );
};

