                                  <Icons.Diamond className="w-4 h-4 fill-current animate-bounce" />
                                  <span className="font-bold text-sm">Gift</span>
                               </>
                          )}
                      </button>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

