            setStatus('success');
            sounds.playWin(); // Success sound
            // Wait a bit on success screen then complete
            setTimeout(() => {
                setIsClosing(true);
                setTimeout(() => {
                    onComplete();
                }, 300);
            }, 1000);
        }, 1500);
    };

    const handleCancel = () => {
