                      >
                         <Icons.Video className="w-5 h-5" /> Watch Replay
                      </button>
                  )}

                  <div className="flex flex-col gap-3 relative z-10">
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onBack(); }} className="w-full py-3 bg-stone-800 text-white dark:bg-stone-100 dark:text-stone-900 rounded-xl font-medium hover:bg-stone-700 dark:hover:bg-stone-200 active:scale-95 transition shadow-lg active:opacity-80">Back to Levels</button>
                    <button onClick={(e) => { e.stopPropagation(); onReturnToMenu(); }} className="w-full py-3 bg-white text-stone-600 border border-stone-200 dark:bg-stone-800 dark:text-stone-200 dark:border-stone-600 rounded-xl font-medium hover:bg-stone-50 dark:hover:bg-stone-700 active:scale-95 transition active:opacity-80">Back to Menu</button>
                  </div>
              </div>
          </div>
      )}

      {/* Video Replay Overlay */}
      {showReplay && replayUrl && (
          <div className="fixed inset-0 bg-black z-[110] flex flex-col items-center justify-center animate-fade-in">
               <div className="relative w-full max-w-lg aspect-square bg-stone-900 shadow-2xl overflow-hidden rounded-none sm:rounded-2xl">
                    <video 
