                   >
                       <Icons.Diamond className="w-5 h-5 text-blue-500" /> Share
                   </button>
                   <button 
                       onClick={() => setShowReplay(false)}
                       className="p-4 bg-stone-800 text-white rounded-full font-bold shadow-xl active:scale-95 transition"
