    // Number input (C Major Pentatonic)
    playNumber(num: number) {
        this.vibrate(8);
        const freqs = [
            523.25, // C5
            587.33, // D5
            659.25, // E5
            783.99, // G5
            880.00, // A5
            1046.50, // C6
            1174.66, // D6
            1318.51, // E6
            1567.98  // G6
        ];
        const freq = freqs[num - 1] || 440;
        // Boosted from 0.45 -> 0.6 for clear feedback
        this.playTone(freq, 'sine', 0.15, 0.6); 
    }

    // Action confirmation (Purchase, etc.)
    playPop() {
        this.vibrate(15);
        // Boosted from 0.5 -> 0.65
        this.playTone(400, 'sine', 0.15, 0.65); 
    }

    // Level Enter Sound (Gentle slide up)
    playLevelEnter() {
        this.vibrate(20);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sine';
            const t = ctx.currentTime;

            // Slide from G4 to C5
            osc.frequency.setValueAtTime(392.00, t); 
            osc.frequency.exponentialRampToValueAtTime(523.25, t + 0.2);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.5, t + 0.05); // Boosted from 0.4 -> 0.5
            gain.gain.linearRampToValueAtTime(0.4, t + 0.15);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);

            osc.start(t);
            osc.stop(t + 0.3);
        } catch (e) {}
    }

    // Section (Row/Col/Box) Complete
    playSectionComplete() {
        this.vibrate(15);
        if (!this.soundEnabled) return;
        try {
            // Soft major triad arpeggio (A Major)
            const notes = [440, 554.37, 659.25]; // A4, C#5, E5
            notes.forEach((freq, i) => {
                // Boosted from 0.25 -> 0.35 (Lower because 3 play rapidly)
                setTimeout(() => this.playTone(freq, 'sine', 0.1, 0.35), i * 50); 
            });
        } catch (e) {}
    }

    // Auto Skill
    playZap() {
        this.vibrate(12);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sine';
            const t = ctx.currentTime;

            osc.frequency.setValueAtTime(1200, t);
            osc.frequency.exponentialRampToValueAtTime(600, t + 0.15);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.5, t + 0.01); // Boosted 0.4 -> 0.5
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);

            osc.start(t);
            osc.stop(t + 0.2);
        } catch (e) {}
    }

    // Scan Skill
    playScan() {
        this.vibrate(20);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'triangle';
            const t = ctx.currentTime;

            osc.frequency.setValueAtTime(200, t);
            osc.frequency.linearRampToValueAtTime(800, t + 0.8);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.35, t + 0.1); // Boosted 0.25 -> 0.35
            gain.gain.linearRampToValueAtTime(0.35, t + 0.6);
            gain.gain.linearRampToValueAtTime(0, t + 0.8);

            osc.start(t);
            osc.stop(t + 0.8);
        } catch (e) {}
    }

    // Reveal Skill
    playReveal() {
        this.vibrate(25); 
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            // E Major 9 chord
            const freqs = [329.63, 415.30, 493.88, 622.25, 739.99]; 

            freqs.forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();

                osc.connect(gain);
                gain.connect(ctx.destination);

                osc.type = 'sine';
                osc.frequency.setValueAtTime(freq, t);

                const start = t + (i * 0.04);
                gain.gain.setValueAtTime(0, start);
                gain.gain.linearRampToValueAtTime(0.3, start + 0.05); // Boosted 0.25 -> 0.3
                gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0);

                osc.start(start);
                osc.stop(start + 2.0);
            });
        } catch (e) {}
    }

    playWin() {
        this.vibrate([50, 50, 50, 50, 100]);
        if (!this.soundEnabled) return;
        const notes = [523.25, 659.25, 783.99, 1046.50]; // C Major
        notes.forEach((freq, i) => {
            setTimeout(() => {
                this.playTone(freq, 'sine', 0.5, 0.6); // Boosted 0.5 -> 0.6
            }, i * 100);
        });
    }
}

