import { Icons } from './ui/Icons';
import { sounds } from '../utils/sound';
import { generateReplayVideo, ReplayMove } from '../utils/replay';

// Hooks
import { useGameTimer } from '../hooks/useGameTimer';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';

// Components
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen?: boolean;
  backgroundClass?: string;
  numberColor?: string;
  purchasedSkills?: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onReturnToMenu, 
  onComplete, 
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen = false,
  backgroundClass = 'bg-paper',
  numberColor = 'text-blue-600',
  purchasedSkills = [],
}) => {

  // Game State
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);
  const [displayedPoints, setDisplayedPoints] = useState(0);
  const [isResuming, setIsResuming] = useState(false);
  const [isRestarting, setIsRestarting] = useState(false);
  const [isQuitting, setIsQuitting] = useState(false);
  const [showDeselectHint, setShowDeselectHint] = useState(false);

  // Replay
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [showReplay, setShowReplay] = useState(false);

  // Section Animation
  const prevCompletedSections = useRef<Set<string>>(new Set());
  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const isFirstLoad = useRef(true);

  // --- HOOKS ---

  const { timer, setTimer } = useGameTimer(settings, isPaused, isCompleted, isEnding, isSettingsOpen);

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick: hookCellClick,
      handleNumberInput: hookNumberInput,
      handleUndo: hookUndo,
      handleErase: hookErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: (completedBoard) => {
          setIsEnding(true);
          setTimeout(() => {
              sounds.playWin();
              setIsCompleted(true);
              const points = getPointsForDifficulty(difficulty);
              setEarnedPoints(points);
              onEarnPoints(points);
              const progress: LevelProgress = { 
                  levelId, 
                  difficulty, 
                  status: 'completed', 
                  timeElapsed: timer, 
                  lastPlayed: Date.now(), 
                  boardState: undefined 
              };
              Storage.saveLevelProgress(progress);
          }, 1000);
      }
  });

  const {
      scanUses, setScanUses, isScanning, scanCooldown,
      revealUses, setRevealUses, revealingCell, setRevealingCell,
      animatingCell, isAutoAvailable,
      handleAutoFill, handleScan, handleReveal
  } = useGameSkills({
      board, setBoard, solvedBoard, setHistory, moveLog,
      selectedCell, activeNumber, settings, difficulty,
      removeNotesFromPeers, checkCompletion,
      onSaveProgress: (b, s, r) => saveProgressInstant(b, s, r)
  });

  // --- REPLAY GENERATION (Triggered by isCompleted) ---

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);
        setTimeout(() => {
            const cleanMoves: ReplayMove[] = [];
            const finalMoveMap = new Map<string, number>();
            moveLog.current.forEach(move => {
                if (move.v === solvedBoard[move.r][move.c]) {
                    finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                }
            });
            for(let r=0; r<9; r++) {
                for(let c=0; c<9; c++) {
                    if (!initialBoardRef.current[r][c].isFixed) {
                        const t = finalMoveMap.get(`${r}-${c}`) || 0;
                        cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                    }
                }
            }
            cleanMoves.sort((a, b) => (a as any).t - (b as any).t);
            const isDark = document.documentElement.classList.contains('dark');
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark).then(url => {
                setReplayUrl(url);
                setIsGeneratingReplay(false);
            });
        }, 500);
  };

  useEffect(() => {
      if (isCompleted && settings.generateReplay && !isGeneratingReplay && !replayUrl) {
          generateReplay();
      }
  }, [isCompleted, settings.generateReplay, isGeneratingReplay, replayUrl]);


  // --- EFFECTS & HELPERS ---

  useEffect(() => {
      setLoading(true);
      isFirstLoad.current = true;
      setShowRestartConfirm(false);
      setIsPaused(false);
      setIsCompleted(false);
      setIsEnding(false);
      setIsResuming(false);
      setIsRestarting(false);
      setIsQuitting(false);
      setEarnedPoints(0);
      setDisplayedPoints(0);
      setShowDeselectHint(false);
      setReplayUrl(null);
      setIsGeneratingReplay(false);
      setShowReplay(false);

      // Reset Tracking
      prevCompletedSections.current = new Set();
      setAnimatingSections(new Set());

      const savedProgress = Storage.getLevelProgress(difficulty, levelId);
      if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
          initializeBoard(savedProgress.boardState);
          setTimer(savedProgress.timeElapsed);
          setScanUses(savedProgress.scanUses !== undefined ? savedProgress.scanUses : 3);
          setRevealUses(savedProgress.revealUses !== undefined ? savedProgress.revealUses : 1);
      } else {
          initializeBoard();
          setTimer(0);
          setScanUses(3);
          setRevealUses(1);
      }
      setLoading(false);
  }, [difficulty, levelId, initializeBoard, setTimer, setScanUses, setRevealUses]);

  // Section Animation Logic
  useEffect(() => {
    if (loading || isPaused || isCompleted || board.length === 0 || solvedBoard.length === 0) return;

    const currentCompleted = new Set<string>();
    // Check Rows
    for(let r=0; r<9; r++) {
        if (board[r].every((cell, cIndex) => cell.value === solvedBoard[r][cIndex])) currentCompleted.add(`row-${r}`);
    }
    // Check Cols
    for(let c=0; c<9; c++) {
        let complete = true;
        for(let r=0; r<9; r++) if (board[r][c].value !== solvedBoard[r][c]) { complete = false; break; }
        if (complete) currentCompleted.add(`col-${c}`);
    }
    // Check Boxes
    for(let b=0; b<9; b++) {
        let complete = true;
        const startR = Math.floor(b/3)*3;
        const startC = (b%3)*3;
        for(let i=0; i<3; i++) for(let j=0; j<3; j++) if (board[startR+i][startC+j].value !== solvedBoard[startR+i][startC+j]) { complete = false; break; }
        if (complete) currentCompleted.add(`box-${b}`);
    }

    if (isFirstLoad.current) {
        prevCompletedSections.current = currentCompleted;
        isFirstLoad.current = false;
        return;
    }

    const newSections = new Set<string>();
    currentCompleted.forEach(id => { if (!prevCompletedSections.current.has(id)) newSections.add(id); });

    if (newSections.size > 0 && !isEnding) {
        sounds.playSectionComplete();
        setAnimatingSections(prev => { const next = new Set(prev); newSections.forEach(s => next.add(s)); return next; });
        setTimeout(() => {
            setAnimatingSections(prev => { const next = new Set(prev); newSections.forEach(s => next.delete(s)); return next; });
        }, 1000); 
    }
    prevCompletedSections.current = currentCompleted;
  }, [board, solvedBoard, loading, isPaused, isCompleted, isEnding]);

  // Points Animation
  useEffect(() => {
      if (isCompleted && earnedPoints > 0) {
          let startTime: number;
          const duration = 1500;
          const animate = (time: number) => {
              if (!startTime) startTime = time;
              const elapsed = time - startTime;
              const progress = Math.min(elapsed / duration, 1);
              const ease = 1 - Math.pow(1 - progress, 4);
              setDisplayedPoints(Math.floor(ease * earnedPoints));
              if (progress < 1) requestAnimationFrame(animate);
              else setDisplayedPoints(earnedPoints);
          };
          requestAnimationFrame(animate);
      }
  }, [isCompleted, earnedPoints]);

  const saveProgressInstant = (currentBoard: Board, currentScanUses?: number, currentRevealUses?: number) => {
     if (loading || isCompleted) return;
     const progress: LevelProgress = {
        levelId, difficulty, status: 'in-progress',
        timeElapsed: timer, lastPlayed: Date.now(), boardState: currentBoard,
        scanUses: currentScanUses !== undefined ? currentScanUses : scanUses,
        revealUses: currentRevealUses !== undefined ? currentRevealUses : revealUses,
      };
      Storage.saveLevelProgress(progress);
  };

  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm || isEnding) return;
    const save = setInterval(() => saveProgressInstant(board), 5000);
    return () => clearInterval(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm, isEnding, scanUses, revealUses]);

  useEffect(() => {
    if (!loading) {
        const t1 = setTimeout(() => setShowDeselectHint(true), 100);
        const t2 = setTimeout(() => setShowDeselectHint(false), 7100);
        return () => { clearTimeout(t1); clearTimeout(t2); };
    }
  }, [loading]);

  const getPointsForDifficulty = (diff: Difficulty) => {
      switch(diff) {
          case Difficulty.SuperEasy: return 5;
          case Difficulty.Easy: return 10;
          case Difficulty.Normal: return 15;
          case Difficulty.Hard: return 20;
          case Difficulty.Intense: return 30;
          case Difficulty.Impossible: return 50;
          default: return 0;
      }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      sounds.playClick();
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());

          // Detect correct extension based on actual blob type
          // If the browser fell back to WebM, we MUST use .webm for it to be valid
          // If the browser managed MP4, we use .mp4
          const isMp4 = blob.type.toLowerCase().includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';

          const file = new File([blob], `sudoku-replay.${ext}`, { type: blob.type });
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Minimal Sudoku Replay',
                  text: `I just solved Level ${levelId} on ${difficulty}!`
              });
          } else {
               const a = document.createElement('a');
               a.href = replayUrl;
               a.download = `sudoku-replay-${difficulty}-${levelId}.${ext}`;
               a.click();
          }
      } catch (e) {
          console.error("Sharing failed", e);
      }
  };

  const handleCellClick = (e: React.MouseEvent, r: number, c: number) => {
      e.stopPropagation();
      if (!revealingCell && !isScanning && !isEnding && !isSettingsOpen) {
          hookCellClick(r, c, isPaused, isCompleted);
      }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleRestart = () => {
      sounds.playClick();
      setIsRestarting(true);
      setTimeout(() => { Storage.clearLevelProgress(difficulty, levelId); initializeBoard(); setTimer(0); setScanUses(3); setRevealUses(1); setIsRestarting(false); setShowRestartConfirm(false); }, 300);
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center text-t-primary">Loading...</div>;

  return (
    <div className={`flex-1 flex flex-col w-full max-w-lg mx-auto relative ${isQuitting ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={() => setSelectedCell(null)}>

      {/* Header */}
      <div className="flex-none pb-2 px-6 w-full relative z-20 min-h-[60px] pt-[20px]">
        <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onBack(); }} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6 text-t-icon" /></button>
        <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center pointer-events-none top-[60px]">
            <span className="text-xs font-bold tracking-wider text-t-secondary uppercase text-center w-48">{difficulty} &bull; Level {levelId}</span>
            {settings.showTimer && <span className="text-2xl font-medium tabular-nums text-t-primary">{formatTime(timer)}</span>}
        </div>
        <div className="absolute right-6 flex flex-col items-end gap-1 -mr-2 top-[20px]">
            <div className="flex gap-1">
                <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200 transition"><Icons.Pause className="w-6 h-6 text-t-icon" /></button>
                <button onClick={(e) => { e.stopPropagation(); onSettingsOpen(); }} className="p-2 rounded-full hover:bg-stone-200 transition"><Icons.Settings className="w-6 h-6 text-t-icon" /></button>
            </div>
            <div className="flex items-center gap-1 bg-stone-100 px-2 py-1 rounded-full mr-1">
                <span className="text-xs font-bold text-stone-600 tabular-nums">{currentPoints}</span>
                <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
            </div>
        </div>
      </div>

      {/* Grid */}
      <SudokuGrid 
          board={board}
          selectedCell={selectedCell}
          activeNumber={activeNumber}
          conflicts={conflicts}
          revealingCell={revealingCell}
          animatingCell={animatingCell}
          isScanning={isScanning}
          animatingSections={animatingSections}
          settings={settings}
          numberColor={numberColor}
          onCellClick={handleCellClick}
      />

      {/* Controls & Numpad */}
      <div className="flex-none w-full max-w-lg flex flex-col gap-2 px-4 pb-2">
          <GameControls 
              canUndo={history.length > 0 && !isPaused && !isCompleted}
              canErase={!!selectedCell && !board[selectedCell[0]][selectedCell[1]].isFixed && !isPaused && !isCompleted}
              isPencilMode={isPencilMode}
              onUndo={(e) => { e.stopPropagation(); hookUndo(isPaused, isCompleted); }}
              onErase={(e) => { e.stopPropagation(); hookErase(isPaused, isCompleted); }}
              onTogglePencil={(e) => { e.stopPropagation(); sounds.playClick(); setIsPencilMode(!isPencilMode); }}
              purchasedSkills={purchasedSkills}
              isAutoAvailable={isAutoAvailable}
              scanUses={scanUses}
              isScanning={isScanning}
              scanCooldown={scanCooldown}
              revealUses={revealUses}
              revealingCell={revealingCell}
              onAutoFill={(e) => { e.stopPropagation(); handleAutoFill(purchasedSkills); }}
              onScan={(e) => { e.stopPropagation(); handleScan(isPaused, isCompleted); }}
              onReveal={(e) => { e.stopPropagation(); handleReveal(isPaused, isCompleted); }}
          />

          <NumberPad 
              activeNumber={activeNumber}
              numberCounts={numberCounts}
              isPencilMode={isPencilMode}
              numberColor={numberColor}
              onNumberClick={(e, num) => { e.stopPropagation(); hookNumberInput(num, isPaused, isCompleted); }}
          />

          <div className={`w-full text-center mt-[4px] pointer-events-none transition-opacity duration-1000 ${showDeselectHint && !settings.digitFirst ? 'opacity-100' : 'opacity-0'}`}>
              <span className="text-xs font-bold text-t-secondary tracking-widest">TAP HERE TO DESELECT</span>
          </div>
      </div>

      {/* Overlays */}

      {(isPaused || showRestartConfirm) && (
          <div className={`fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center ${(isResuming || isRestarting) ? 'animate-fade-out' : 'animate-fade-in'}`}>
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setIsResuming(true); setTimeout(() => { setIsPaused(false); setIsResuming(false); }, 300); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90"><Icons.Play className="w-5 h-5" /> Resume</button>
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec"><Icons.Reset className="w-5 h-5" /> Restart Level</button>
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition">Quit Game</button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3"><button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button><button onClick={(e) => { e.stopPropagation(); handleRestart(); }} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button></div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={displayedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              onReplay={(e) => { e.stopPropagation(); sounds.playClick(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onBack={(e) => { e.stopPropagation(); sounds.playClick(); onBack(); }}
              onReturnToMenu={(e) => { e.stopPropagation(); onReturnToMenu(); }}
          />
      )}
    </div>
  );
}

import React from 'react';
import { Board, Cell, AppSettings } from '../../types';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
}

export const SudokuGrid: React.FC<SudokuGridProps> = ({
    board,
    selectedCell,
    activeNumber,
    conflicts,
    revealingCell,
    animatingCell,
    isScanning,
    animatingSections,
    settings,
    numberColor,
    onCellClick
}) => {
    const squareSize = 'min(96vw, 53dvh)';
    const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
    const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
    const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

    const getCellClass = (cell: Cell, r: number, c: number) => {
        let classes = "w-full h-full flex items-center justify-center cursor-pointer select-none relative overflow-hidden ";
        const isConflict = conflicts.has(`${r}-${c}`);
        const isError = cell.isError;
        const isMarkedWrong = cell.isMarkedWrong;
        const isRevealed = cell.isRevealed;

        // Highlight Logic
        const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;

        let isSameValue = false;
        if (settings.digitFirst) {
            if (activeNumber !== null) {
                isSameValue = cell.value === activeNumber;
            } else if (selectedCell && cell.value !== null) {
                 isSameValue = board[selectedCell[0]][selectedCell[1]].value === cell.value;
            }
        } else {
            isSameValue = selectedCell && cell.value !== null && board[selectedCell[0]][selectedCell[1]].value === cell.value;
        }

        const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

        let bgClass = ''; 
        const isThisCellRevealing = revealingCell?.r === r && revealingCell?.c === c;

        if (isThisCellRevealing) {
            bgClass = ''; 
        } else if (isMarkedWrong) {
             bgClass = 'bg-red-200 animate-pulse '; 
        } else if (isError || isConflict) {
             bgClass = 'bg-red-50 ';
        } else if (isSelected) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isSameValue) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isRelated) {
             bgClass = 'bg-stone-200/60 dark:bg-stone-100/50 '; 
        } else if (isRevealed) {
             bgClass = 'bg-amber-100 '; 
        } else {
             bgClass = 'bg-t-board '; 
        }

        classes += bgClass;

        if (isSelected && (isError || isConflict || isMarkedWrong)) {
            classes += "ring-2 ring-inset ring-red-400 z-10 ";
        }

        if (isThisCellRevealing) {
            classes += "animate-reveal-premium z-50 relative ";
        }

        if (cell.isFixed) {
            classes += "font-semibold text-stone-800 ";
        } else if (isRevealed) {
            classes += "font-semibold text-stone-800 ";
        } else {
            if (isError || isConflict || isMarkedWrong) {
                classes += "font-medium text-red-500 ";
            } else {
                classes += "font-medium ";
            }
        }
        return classes;
    };

    const getSectionOverlayStyle = (sectionId: string) => {
        const [type, idxStr] = sectionId.split('-');
        const index = parseInt(idxStr);
        const style: React.CSSProperties = { position: 'absolute', pointerEvents: 'none', zIndex: 40 };

        if (type === 'row') {
            style.top = `${(index / 9) * 100}%`;
            style.left = '0';
            style.width = '100%';
            style.height = `${100 / 9}%`;
        } else if (type === 'col') {
            style.left = `${(index / 9) * 100}%`;
            style.top = '0';
            style.height = '100%';
            style.width = `${100 / 9}%`;
        } else if (type === 'box') {
            const r = Math.floor(index / 3);
            const c = index % 3;
            style.top = `${(r * 3 / 9) * 100}%`;
            style.left = `${(c * 3 / 9) * 100}%`;
            style.width = `${100 / 3}%`;
            style.height = `${100 / 3}%`;
        }
        return style;
    };

    return (
        <div className="flex-none w-full flex flex-col items-center justify-start min-h-0 px-0 pb-2 pt-10">
            <div className="bg-t-board border-2 border-stone-800 rounded-lg overflow-hidden relative flex-none shadow-lg" style={{ width: squareSize, height: squareSize, maxWidth: '500px', maxHeight: '500px' }}>

            {isScanning && (
                <div className="absolute left-0 right-0 h-1 bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)] z-30 animate-scan pointer-events-none"></div>
            )}

            {/* Section Completion Borders */}
            {Array.from(animatingSections).map((sectionId: string) => (
                 <div 
                    key={sectionId} 
                    className="border-2 border-emerald-400/80 shadow-[0_0_15px_rgba(52,211,153,0.6)] animate-section-complete"
                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}

            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #a8a29e; stroke-width: 0.05; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.05; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;

                    return (
                        <div key={`${rIndex}-${cIndex}`} className={getCellClass(cell, rIndex, cIndex)} onClick={(e) => onCellClick(e, rIndex, cIndex)} style={{ fontSize: mainFontSize }}>
                        {(cell.value || isAnimating) ? (
                            <span className={`leading-none pt-[0.1em] ${!cell.isFixed && !cell.isError && !cell.isMarkedWrong && !cell.isRevealed ? numberColor : ''}`}>
                                {isAnimating ? animatingCell!.value : cell.value}
                            </span>
                        ) : (
                            <div className="grid grid-cols-3 grid-rows-3 w-full h-full p-[1px] pointer-events-none">
                                {[1,2,3,4,5,6,7,8,9].map(n => (
                                    <div key={n} className="flex items-center justify-center leading-none" style={{ fontSize: noteFontSize, lineHeight: noteLineHeight }}>
                                        <span className={cell.notes.includes(n) ? 'text-stone-500' : 'invisible'}>{n}</span>
                                    </div>
                                ))}
                            </div>
                        )}
                        </div>
                    );
                })
            )}
            </div>
         </div>
         </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Difficulty, LevelProgress, AppSettings, Board } from '../types';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';
import { sounds } from '../utils/sound';
import { generateReplayVideo, ReplayMove } from '../utils/replay';

// Hooks
import { useGameTimer } from '../hooks/useGameTimer';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';

// Components
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen?: boolean;
  backgroundClass?: string;
  numberColor?: string;
  purchasedSkills?: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onReturnToMenu, 
  onComplete, 
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen = false,
  backgroundClass = 'bg-paper',
  numberColor = 'text-blue-600',
  purchasedSkills = [],
}) => {

  // Game State
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);
  const [displayedPoints, setDisplayedPoints] = useState(0);
  const [isResuming, setIsResuming] = useState(false);
  const [isRestarting, setIsRestarting] = useState(false);
  const [isQuitting, setIsQuitting] = useState(false);
  const [showDeselectHint, setShowDeselectHint] = useState(false);

  // Replay
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [showReplay, setShowReplay] = useState(false);

  // Section Animation
  const prevCompletedSections = useRef<Set<string>>(new Set());
  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const isFirstLoad = useRef(true);

  // --- HOOKS ---

  const { timer, setTimer } = useGameTimer(settings, isPaused, isCompleted, isEnding, isSettingsOpen);

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick: hookCellClick,
      handleNumberInput: hookNumberInput,
      handleUndo: hookUndo,
      handleErase: hookErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: (completedBoard) => {
          setIsEnding(true);
          setTimeout(() => {
              sounds.playWin();
              setIsCompleted(true);
              const points = getPointsForDifficulty(difficulty);
              setEarnedPoints(points);
              onEarnPoints(points);
              const progress: LevelProgress = { 
                  levelId, 
                  difficulty, 
                  status: 'completed', 
                  timeElapsed: timer, 
                  lastPlayed: Date.now(), 
                  boardState: undefined 
              };
              Storage.saveLevelProgress(progress);
          }, 1000);
      }
  });

  const {
      scanUses, setScanUses, isScanning, scanCooldown,
      revealUses, setRevealUses, revealingCell, setRevealingCell,
      animatingCell, isAutoAvailable,
      handleAutoFill, handleScan, handleReveal
  } = useGameSkills({
      board, setBoard, solvedBoard, setHistory, moveLog,
      selectedCell, activeNumber, settings, difficulty,
      removeNotesFromPeers, checkCompletion,
      onSaveProgress: (b, s, r) => saveProgressInstant(b, s, r)
  });

  // --- REPLAY GENERATION (Triggered by isCompleted) ---

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);
        setTimeout(() => {
            const cleanMoves: ReplayMove[] = [];
            const finalMoveMap = new Map<string, number>();
            moveLog.current.forEach(move => {
                if (move.v === solvedBoard[move.r][move.c]) {
                    finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                }
            });
            for(let r=0; r<9; r++) {
                for(let c=0; c<9; c++) {
                    if (!initialBoardRef.current[r][c].isFixed) {
                        const t = finalMoveMap.get(`${r}-${c}`) || 0;
                        cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                    }
                }
            }
            cleanMoves.sort((a, b) => (a as any).t - (b as any).t);
            const isDark = document.documentElement.classList.contains('dark');
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark).then(url => {
                setReplayUrl(url);
                setIsGeneratingReplay(false);
            });
        }, 500);
  };

  useEffect(() => {
      if (isCompleted && settings.generateReplay && !isGeneratingReplay && !replayUrl) {
          generateReplay();
      }
  }, [isCompleted, settings.generateReplay, isGeneratingReplay, replayUrl]);


  // --- EFFECTS & HELPERS ---

  useEffect(() => {
      setLoading(true);
      isFirstLoad.current = true;
      setShowRestartConfirm(false);
      setIsPaused(false);
      setIsCompleted(false);
      setIsEnding(false);
      setIsResuming(false);
      setIsRestarting(false);
      setIsQuitting(false);
      setEarnedPoints(0);
      setDisplayedPoints(0);
      setShowDeselectHint(false);
      setReplayUrl(null);
      setIsGeneratingReplay(false);
      setShowReplay(false);

      // Reset Tracking
      prevCompletedSections.current = new Set();
      setAnimatingSections(new Set());

      const savedProgress = Storage.getLevelProgress(difficulty, levelId);
      if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
          initializeBoard(savedProgress.boardState);
          setTimer(savedProgress.timeElapsed);
          setScanUses(savedProgress.scanUses !== undefined ? savedProgress.scanUses : 3);
          setRevealUses(savedProgress.revealUses !== undefined ? savedProgress.revealUses : 1);
      } else {
          initializeBoard();
          setTimer(0);
          setScanUses(3);
          setRevealUses(1);
      }
      setLoading(false);
  }, [difficulty, levelId, initializeBoard, setTimer, setScanUses, setRevealUses]);

  // Section Animation Logic
  useEffect(() => {
    if (loading || isPaused || isCompleted || board.length === 0 || solvedBoard.length === 0) return;

    const currentCompleted = new Set<string>();
    // Check Rows
    for(let r=0; r<9; r++) {
        if (board[r].every((cell, cIndex) => cell.value === solvedBoard[r][cIndex])) currentCompleted.add(`row-${r}`);
    }
    // Check Cols
    for(let c=0; c<9; c++) {
        let complete = true;
        for(let r=0; r<9; r++) if (board[r][c].value !== solvedBoard[r][c]) { complete = false; break; }
        if (complete) currentCompleted.add(`col-${c}`);
    }
    // Check Boxes
    for(let b=0; b<9; b++) {
        let complete = true;
        const startR = Math.floor(b/3)*3;
        const startC = (b%3)*3;
        for(let i=0; i<3; i++) for(let j=0; j<3; j++) if (board[startR+i][startC+j].value !== solvedBoard[startR+i][startC+j]) { complete = false; break; }
        if (complete) currentCompleted.add(`box-${b}`);
    }

    if (isFirstLoad.current) {
        prevCompletedSections.current = currentCompleted;
        isFirstLoad.current = false;
        return;
    }

    const newSections = new Set<string>();
    currentCompleted.forEach(id => { if (!prevCompletedSections.current.has(id)) newSections.add(id); });

    if (newSections.size > 0 && !isEnding) {
        sounds.playSectionComplete();
        setAnimatingSections(prev => { const next = new Set(prev); newSections.forEach(s => next.add(s)); return next; });
        setTimeout(() => {
            setAnimatingSections(prev => { const next = new Set(prev); newSections.forEach(s => next.delete(s)); return next; });
        }, 1000); 
    }
    prevCompletedSections.current = currentCompleted;
  }, [board, solvedBoard, loading, isPaused, isCompleted, isEnding]);

  // Points Animation
  useEffect(() => {
      if (isCompleted && earnedPoints > 0) {
          let startTime: number;
          const duration = 1500;
          const animate = (time: number) => {
              if (!startTime) startTime = time;
              const elapsed = time - startTime;
              const progress = Math.min(elapsed / duration, 1);
              const ease = 1 - Math.pow(1 - progress, 4);
              setDisplayedPoints(Math.floor(ease * earnedPoints));
              if (progress < 1) requestAnimationFrame(animate);
              else setDisplayedPoints(earnedPoints);
          };
          requestAnimationFrame(animate);
      }
  }, [isCompleted, earnedPoints]);

  const saveProgressInstant = (currentBoard: Board, currentScanUses?: number, currentRevealUses?: number) => {
     if (loading || isCompleted) return;
     const progress: LevelProgress = {
        levelId, difficulty, status: 'in-progress',
        timeElapsed: timer, lastPlayed: Date.now(), boardState: currentBoard,
        scanUses: currentScanUses !== undefined ? currentScanUses : scanUses,
        revealUses: currentRevealUses !== undefined ? currentRevealUses : revealUses,
      };
      Storage.saveLevelProgress(progress);
  };

  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm || isEnding) return;
    const save = setInterval(() => saveProgressInstant(board), 5000);
    return () => clearInterval(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm, isEnding, scanUses, revealUses]);

  useEffect(() => {
    if (!loading) {
        const t1 = setTimeout(() => setShowDeselectHint(true), 100);
        const t2 = setTimeout(() => setShowDeselectHint(false), 7100);
        return () => { clearTimeout(t1); clearTimeout(t2); };
    }
  }, [loading]);

  const getPointsForDifficulty = (diff: Difficulty) => {
      switch(diff) {
          case Difficulty.SuperEasy: return 5;
          case Difficulty.Easy: return 10;
          case Difficulty.Normal: return 15;
          case Difficulty.Hard: return 20;
          case Difficulty.Intense: return 30;
          case Difficulty.Impossible: return 50;
          default: return 0;
      }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      sounds.playClick();
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());

          // Detect correct extension based on actual blob type
          // If the browser fell back to WebM, we MUST use .webm for it to be valid
          // If the browser managed MP4, we use .mp4
          const isMp4 = blob.type.toLowerCase().includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';

          const file = new File([blob], `sudoku-replay.${ext}`, { type: blob.type });
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Minimal Sudoku Replay',
                  text: `I just solved Level ${levelId} on ${difficulty}!`
              });
          } else {
               const a = document.createElement('a');
               a.href = replayUrl;
               a.download = `sudoku-replay-${difficulty}-${levelId}.${ext}`;
               a.click();
          }
      } catch (e) {
          console.error("Sharing failed", e);
      }
  };

  const handleCellClick = (e: React.MouseEvent, r: number, c: number) => {
      e.stopPropagation();
      if (!revealingCell && !isScanning && !isEnding && !isSettingsOpen) {
          hookCellClick(r, c, isPaused, isCompleted);
      }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleRestart = () => {
      sounds.playClick();
      setIsRestarting(true);
      setTimeout(() => { Storage.clearLevelProgress(difficulty, levelId); initializeBoard(); setTimer(0); setScanUses(3); setRevealUses(1); setIsRestarting(false); setShowRestartConfirm(false); }, 300);
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center text-t-primary">Loading...</div>;

  return (
    <div className={`flex-1 flex flex-col w-full max-w-lg mx-auto relative ${isQuitting ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={() => setSelectedCell(null)}>

      {/* Header */}
      <div className="flex-none pb-2 px-6 w-full relative z-20 min-h-[60px] pt-[20px]">
        <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onBack(); }} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6 text-t-icon" /></button>
        <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center pointer-events-none top-[60px]">
            <span className="text-xs font-bold tracking-wider text-t-secondary uppercase text-center w-48">{difficulty} &bull; Level {levelId}</span>
            {settings.showTimer && <span className="text-2xl font-medium tabular-nums text-t-primary">{formatTime(timer)}</span>}
        </div>
        <div className="absolute right-6 flex flex-col items-end gap-1 -mr-2 top-[20px]">
            <div className="flex gap-1">
                <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200 transition"><Icons.Pause className="w-6 h-6 text-t-icon" /></button>
                <button onClick={(e) => { e.stopPropagation(); onSettingsOpen(); }} className="p-2 rounded-full hover:bg-stone-200 transition"><Icons.Settings className="w-6 h-6 text-t-icon" /></button>
            </div>
            <div className="flex items-center gap-1 bg-stone-100 px-2 py-1 rounded-full mr-1">
                <span className="text-xs font-bold text-stone-600 tabular-nums">{currentPoints}</span>
                <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
            </div>
        </div>
      </div>

      {/* Grid */}
      <SudokuGrid 
          board={board}
          selectedCell={selectedCell}
          activeNumber={activeNumber}
          conflicts={conflicts}
          revealingCell={revealingCell}
          animatingCell={animatingCell}
          isScanning={isScanning}
          animatingSections={animatingSections}
          settings={settings}
          numberColor={numberColor}
          onCellClick={handleCellClick}
      />

      {/* Controls & Numpad */}
      <div className="flex-none w-full max-w-lg flex flex-col gap-2 px-4 pb-2 mt-5">
          <GameControls 
              canUndo={history.length > 0 && !isPaused && !isCompleted}
              canErase={!!selectedCell && !board[selectedCell[0]][selectedCell[1]].isFixed && !isPaused && !isCompleted}
              isPencilMode={isPencilMode}
              onUndo={(e) => { e.stopPropagation(); hookUndo(isPaused, isCompleted); }}
              onErase={(e) => { e.stopPropagation(); hookErase(isPaused, isCompleted); }}
              onTogglePencil={(e) => { e.stopPropagation(); sounds.playClick(); setIsPencilMode(!isPencilMode); }}
              purchasedSkills={purchasedSkills}
              isAutoAvailable={isAutoAvailable}
              scanUses={scanUses}
              isScanning={isScanning}
              scanCooldown={scanCooldown}
              revealUses={revealUses}
              revealingCell={revealingCell}
              onAutoFill={(e) => { e.stopPropagation(); handleAutoFill(purchasedSkills); }}
              onScan={(e) => { e.stopPropagation(); handleScan(isPaused, isCompleted); }}
              onReveal={(e) => { e.stopPropagation(); handleReveal(isPaused, isCompleted); }}
          />

          <NumberPad 
              activeNumber={activeNumber}
              numberCounts={numberCounts}
              isPencilMode={isPencilMode}
              numberColor={numberColor}
              onNumberClick={(e, num) => { e.stopPropagation(); hookNumberInput(num, isPaused, isCompleted); }}
          />

          <div className={`w-full text-center mt-[4px] pointer-events-none transition-opacity duration-1000 ${showDeselectHint && !settings.digitFirst ? 'opacity-100' : 'opacity-0'}`}>
              <span className="text-xs font-bold text-t-secondary tracking-widest">TAP HERE TO DESELECT</span>
          </div>
      </div>

      {/* Overlays */}

      {(isPaused || showRestartConfirm) && (
          <div className={`fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center ${(isResuming || isRestarting) ? 'animate-fade-out' : 'animate-fade-in'}`}>
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setIsResuming(true); setTimeout(() => { setIsPaused(false); setIsResuming(false); }, 300); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90"><Icons.Play className="w-5 h-5" /> Resume</button>
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec"><Icons.Reset className="w-5 h-5" /> Restart Level</button>
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition">Quit Game</button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3"><button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button><button onClick={(e) => { e.stopPropagation(); handleRestart(); }} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button></div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={displayedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              onReplay={(e) => { e.stopPropagation(); sounds.playClick(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onBack={(e) => { e.stopPropagation(); sounds.playClick(); onBack(); }}
              onReturnToMenu={(e) => { e.stopPropagation(); onReturnToMenu(); }}
          />
      )}
    </div>
  );
}

import React from 'react';
import { Board, Cell, AppSettings } from '../../types';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
