                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      <button onClick={() => {
                                           if (!isPurchased) {
                                               onPurchase(pack, 'sound');
                                           } else {
                                               onSelectSoundPack(pack.id);
                                           }
                                      }} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isSelected ? 'bg-t-surface ring-2 ring-inset ring-blue-500' : 'bg-t-surface active:scale-95'}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <pack.icon className={`w-8 h-8 text-t-primary`} />
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{pack.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);

    const handleItemClick = (e: React.MouseEvent, id: string, action: () => void) => {
        e.stopPropagation();
        sounds.playClick();
        if (activeTooltipId === id) {
            setActiveTooltipId(null);
        } else {
            setActiveTooltipId(id);
            action();
        }
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={() => setActiveTooltipId(null)}
        >
             <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                  <button onClick={onBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon">
                      <Icons.Back className="w-6 h-6" />
                  </button>
                  <div className="w-full text-center mt-2 pointer-events-none"><h1 className="text-xl font-bold text-t-primary">Store</h1></div>
                  <div className="absolute right-6 top-[20px] flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                      <span className="text-sm font-bold text-t-primary">{points}</span>
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                  </div>
             </div>

             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md space-y-8">

                      {/* SKILLS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-2">{SKILLS.map(skill => {
                              const isPurchased = purchasedSkills.includes(skill.id);
                              const isTooltipActive = activeTooltipId === skill.id;

                              return (
                                  <div key={skill.id} className="flex flex-col items-center gap-1 relative">
                                      {/* Speech Bubble Tooltip */}
                                      {isTooltipActive && (
                                          <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 w-32 z-50 pointer-events-none animate-tooltip-in">
                                              <div className="bg-white dark:bg-stone-100 text-stone-900 shadow-xl text-[10px] p-2 rounded-lg relative text-center leading-tight font-medium border border-stone-200">
                                                  {skill.description}
                                                  <div className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent border-t-white dark:border-t-stone-100"></div>
                                              </div>
                                          </div>
                                      )}

                                      <button 
                                          onClick={(e) => {
                                              if (!isPurchased) {
                                                  onPurchase(skill, 'skill');
                                              } else {
                                                  handleItemClick(e, skill.id, () => {});
                                              }
                                          }} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isPurchased ? 'bg-t-surface ring-2 ring-inset ring-blue-500' : 'bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <skill.icon className={`w-8 h-8 ${skill.class}`} />
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{skill.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{skill.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isSelected && bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const isTooltipActive = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {/* Speech Bubble Tooltip */}
                                      {isTooltipActive && (
                                          <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 w-32 z-50 pointer-events-none animate-tooltip-in">
                                              <div className="bg-white dark:bg-stone-100 text-stone-900 shadow-xl text-[10px] p-2 rounded-lg relative text-center leading-tight font-medium border border-stone-200">
                                                  {pack.description}
                                                  <div className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent border-t-white dark:border-t-stone-100"></div>
                                              </div>
                                          </div>
                                      )}

                                      <button 
                                          onClick={(e) => {
                                              if (!isPurchased) {
                                                  onPurchase(pack, 'sound');
                                              } else {
                                                  handleItemClick(e, pack.id, () => onSelectSoundPack(pack.id));
                                              }
                                          }} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isSelected ? 'bg-t-surface ring-2 ring-inset ring-blue-500' : 'bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <pack.icon className={`w-8 h-8 text-t-primary`} />
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{pack.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};
